mapper.body:
{
  "model": "anthropic/claude-sonnet-4-6",
  "models": ["anthropic/claude-sonnet-4-6", "{{env.OPENROUTER_FALLBACK_MODEL}}"],
  "route": "fallback",
  "provider": { "allow_fallbacks": true },
  "messages": [
    {
      "role": "system",
      "content": "You are a friendly scheduling assistant. Write a short, warm, personalized outreach email (3–4 sentences, no markdown) to a waitlisted contact letting them know a last-minute opening just became available. Encourage them to book before it fills up. Include the date and time of the opening. End with the Calendly booking link. Keep the tone professional but conversational. Do not reveal the previous client cancelled."
    },
    {
      "role": "user",
      "content": "Contact first name: {{5.properties.firstname}}. Opening: {{formatDate(1.body.payload.event.start_time; \"dddd, MMMM D [at] h:mm A\"; \"America/New_York\")}} Eastern Time. Booking link: {{env.CALENDLY_BOOKING_LINK}}"
    }
  ],
  "temperature": 0.7,
  "max_tokens": 300
}

{
  "properties": {
    "hs_timestamp": "{{now}}",
    "hs_note_body": "Last-minute opening outreach sent (Scenario AN). Slot: {{formatDate(1.body.payload.event.start_time; \"YYYY-MM-DD HH:mm\"; \"America/New_York\")}} ET. Email sent to {{5.properties.email}}. AI message generated by claude-sonnet-4-6 via OpenRouter.",
    "hs_attachment_ids": ""
  },
  "associations": [
    {
      "to": { "id": "{{5.id}}" },
      "types": [
        {
          "associationCategory": "HUBSPOT_DEFINED",
          "associationTypeId": 202
        }
      ]
    }
  ]
}
